import {reviewCases, officerView} from './officer.js';
import {APP_VERSION,RULE_VERSION,SOURCES,CATEGORIES,TODAY,money,escapeHTML as e,parseAmount,validateRecord,suggestCategory,parseReceipt,findDuplicates,totals,calculatePresumptive,csv,calendarEvent,ARTICLES,searchGuidance,seedState,validateBackup,validDate} from './core.js';
import {loadState,saveState,putEvidence,getEvidence,deleteEvidence} from './storage.js';
import {download,extractDocument,reportPDF,businessReceiptPDF,estimatePDF} from './io.js';

const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',camera:'M5 6h3l2-3h4l2 3h3a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',records:'M6 3h8l4 4v14H6ZM14 3v5h5M9 12h6M9 16h6',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',help:'M9 9a3 3 0 1 1 5 2c-1 .7-2 1-2 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',down:'M6 6l12 12M6 18h12V6',up:'M6 18 18 6M6 6h12v12',check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',download:'M12 3v12m-5-5 5 5 5-5M4 15v5h16v-5',close:'m6 6 12 12M6 18 18 6',shield:'m12 3 8 4v6c0 5-8 9-8 9s-8-4-8-9V7Zm-4 9 3 3 5-6',clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wallet:'M3 6h16v15H3ZM3 6V3h13v3M15 11h6v5h-6ZM17 13.5h.1',store:'M3 10h18l-2-7H5ZM4 10v11h16V10M9 21v-7h6v7',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M15 15l6 6M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',edit:'m4 16-1 5 5-1L20 8l-4-4ZM13 7l4 4',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 11h16',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7',file:'M6 2h8l5 5v15H6ZM14 2v6h5',wifi:'M3 7a15 15 0 0 1 18 0M6 11a10 10 0 0 1 12 0M9 15a5 5 0 0 1 6 0M12 19h.01',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
let lang='en',theme='light';try{lang=localStorage.getItem('kr-language')==='sw'?'sw':'en';theme=localStorage.getItem('kr-theme')||'light';}catch{}
const t=(en,sw)=>lang==='sw'?(sw||en):en;
let state,storageIssue='';try{state=loadState();}catch(err){state=seedState();storageIssue=err.message;}
let route=location.hash.slice(1)||'overview',month=TODAY.slice(0,7),filter='all',query='',guideQuery='',guideSelected='',busy=false,draft=null,previewURL='',captureMode='scan',lastEstimate=null,lastEstimateInputs=null;
let officerSelected='';
const allowed=['officer','overview','capture','records','tax','help','about','settings','reminders'];if(!allowed.includes(route))route='overview';
const app=document.getElementById('app');
const currency=n=>'TZS '+money(n);
const dateLabel=d=>validDate(d)?new Intl.DateTimeFormat(lang==='sw'?'sw-TZ':'en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Africa/Dar_es_Salaam'}).format(new Date(d+'T12:00:00Z')):d;
const monthLabel=m=>m?new Intl.DateTimeFormat(lang==='sw'?'sw-TZ':'en-GB',{month:'long',year:'numeric',timeZone:'Africa/Dar_es_Salaam'}).format(new Date(m+'-01T12:00:00Z')):t('All periods','Vipindi vyote');
const titleFor={officer:()=>t('Officer review','Uhakiki wa afisa'),overview:()=>t('Overview','Muhtasari'),capture:()=>t('Capture & review','Nasa na hakiki'),records:()=>t('Your records','Kumbukumbu zako'),tax:()=>t('Tax workspace','Makadirio ya kodi'),help:()=>t('Kodi guide','Mwongozo wa Kodi'),about:()=>t('About this prototype','Kuhusu mfano huu'),settings:()=>t('Your workspace','Eneo lako la kazi'),reminders:()=>t('Your reminders','Vikumbusho vyako')};
const btn=(label,action,name='',cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${name?icon(name):''}${label}</button>`;
const routeBtn=(label,to,name='',cls='')=>btn(label,'navigate',name,cls,`data-route="${to}"`);
const source=(key)=>`<a class="source-link" href="${SOURCES[key].url}" target="_blank" rel="noopener noreferrer">${e(SOURCES[key].name)} ${icon('external')}</a>`;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000);}
function commit(change,label,details={}){const next=structuredClone(state);change(next);next.events.push({id:crypto.randomUUID(),at:new Date().toISOString(),action:label,details});if(next.events.length>10000)throw Error('Activity capacity reached. Export a backup before starting a new sandbox.');saveState(next);state=next;storageIssue='';}
function modal(title,body){const root=document.getElementById('modal-root');root.innerHTML=`<dialog aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="${t('Close','Funga')}">${icon('close')}</button></div><div class="dialog-body">${body}</div></dialog>`;const d=root.querySelector('dialog');d.addEventListener('click',ev=>{if(ev.target===d)d.close();});d.showModal();}
function closeModal(){document.querySelector('dialog')?.close();}
function header(title,subtitle,actions=''){return `<div class="page-header"><div><div class="eyebrow">${e(titleFor[route]())}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="buttons">${actions}</div>`:''}</div>`;}
function empty(title,copy,action=''){return `<div class="empty">${icon('records')}<h2>${title}</h2><p>${copy}</p>${action}</div>`;}
function statusBadge(s){return `<span class="badge ${s}">${s==='confirmed'?t('Confirmed','Imethibitishwa'):s==='review'?t('Needs review','Hakiki kwanza'):t('Voided','Imebatilishwa')}</span>`;}
function getDraft(){if(!draft)draft={id:crypto.randomUUID(),type:'expense',date:TODAY,description:'',seller:'',amount:'',vat:'',category:'Other',payment:'Cash',reference:'',source:'manual',text:'',sourceHash:'',sourceId:'',reviewed:false,dirty:false};return draft;}
function tableRows(records,compact=false){return records.map(r=>`<tr><td><div class="record-title"><span class="record-symbol ${r.type}">${icon(r.type==='sale'?'up':'down')}</span><div>${e(r.description)}<div class="record-detail">${e(r.seller||t('No party specified','Jina halijawekwa'))}</div></div></div></td><td class="${compact?'mobile-hide':''}">${e(dateLabel(r.date))}</td><td class="mobile-hide">${categoryLabel(r.category)}</td><td class="number">${r.type==='expense'?'−':''}${money(r.amount)}</td><td>${statusBadge(r.status)}</td><td><button class="icon-btn" data-action="open-record" data-id="${e(r.id)}" aria-label="${e(t('Open record: ','Fungua kumbukumbu: ')+r.description)}">${icon(r.status==='review'?'edit':'chevron')}</button></td></tr>`).join('');}
function recordsTable(records,compact=false){return `<div class="table-wrap"><table><caption class="sr-only">${t('Business records, amounts in TZS','Kumbukumbu za biashara, kiasi kwa TZS')}</caption><thead><tr><th>${t('Transaction','Muamala')}</th><th class="${compact?'mobile-hide':''}">${t('Date','Tarehe')}</th><th class="mobile-hide">${t('Category','Aina')}</th><th class="number">${t('Amount · TZS','Kiasi · TZS')}</th><th>${t('Status','Hali')}</th><th><span class="sr-only">${t('Actions','Vitendo')}</span></th></tr></thead><tbody>${tableRows(records,compact)}</tbody></table></div>`;}
function categoryLabel(c){return lang==='en'?e(c):({Sales:'Mauzo',Stock:'Bidhaa',Transport:'Usafiri',Utilities:'Huduma za matumizi',Rent:'Pango',Equipment:'Vifaa',Services:'Huduma',Other:'Nyingine'}[c]||e(c));}
function cashChart(){const start=new Date(month+'-01T12:00:00Z'),count=new Date(start.getUTCFullYear(),start.getUTCMonth()+1,0).getDate();const buckets=Array.from({length:4},(_,i)=>({label:`${i*7+1}–${i===3?count:(i+1)*7}`,sales:0,expenses:0}));state.records.filter(r=>r.status==='confirmed'&&r.date.startsWith(month)).forEach(r=>{const i=Math.min(3,Math.floor((Number(r.date.slice(-2))-1)/7));buckets[i][r.type==='sale'?'sales':'expenses']+=r.amount;});const max=Math.max(...buckets.flatMap(b=>[b.sales,b.expenses]),100000);const ceil=Math.ceil(max/100000)*100000;const y=v=>178-(v/ceil)*144;return `<svg class="chart" viewBox="0 0 590 212" role="img" aria-label="${t('Weekly confirmed sales and expenses. Exact totals appear above.','Mauzo na matumizi yaliyothibitishwa kwa wiki. Jumla zipo juu.')}"><title>${t('Confirmed movement by week','Miamala iliyothibitishwa kwa wiki')}</title>${[0,1,2,3].map(i=>`<line class="chart-grid" x1="70" y1="${34+i*48}" x2="575" y2="${34+i*48}"/><text x="60" y="${38+i*48}" text-anchor="end">${money(Math.round(ceil*(3-i)/3/1000))}k</text>`).join('')}${buckets.map((b,i)=>{const x=110+i*125;return `<rect x="${x-20}" y="${y(b.sales)}" width="24" height="${178-y(b.sales)}" rx="4" fill="#244ce6"><title>${t('Sales','Mauzo')}: ${currency(b.sales)}</title></rect><rect x="${x+10}" y="${y(b.expenses)}" width="24" height="${178-y(b.expenses)}" rx="4" fill="#85d3b6"><title>${t('Expenses','Matumizi')}: ${currency(b.expenses)}</title></rect><text x="${x+5}" y="203" text-anchor="middle">${b.label}</text>`;}).join('')}</svg>`;}
function overview(){if(!month)month=TODAY.slice(0,7);const sum=totals(state.records,month);const rows=state.records.filter(r=>r.date.startsWith(month)&&r.status!=='void').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return header(t('Your business, clearly recorded.','Biashara yako, kwa kumbukumbu bora.'),t('A clear view of your everyday sales and expenses.','Ona mauzo na matumizi yako ya kila siku.'),btn(t('Record transaction','Rekodi muamala'),'new-record','plus','primary'))+`<div class="stat-grid"><section class="card stat"><div class="stat-top">${t('Sales','Mauzo')}<span class="stat-icon">${icon('up')}</span></div><div class="stat-value"><span class="currency">TZS</span>${money(sum.sales)}</div><div class="stat-foot">${t('Confirmed records','Kumbukumbu zilizothibitishwa')} · ${e(monthLabel(month))}</div></section><section class="card stat"><div class="stat-top">${t('Expenses','Matumizi')}<span class="stat-icon">${icon('wallet')}</span></div><div class="stat-value"><span class="currency">TZS</span>${money(sum.expenses)}</div><div class="stat-foot">${t('Confirmed records','Kumbukumbu zilizothibitishwa')} · ${e(monthLabel(month))}</div></section><section class="card stat review-stat"><div class="stat-top"><span class="stat-icon">${icon('records')}</span><div><strong>${sum.pending?t(`${sum.pending} records need review`,`Kumbukumbu ${sum.pending} zinahitaji uhakiki`):t('All saved records reviewed','Kumbukumbu zote zimehakikiwa')}</strong><p>${t('Only confirmed records count in your totals.','Jumla inajumuisha zilizothibitishwa tu.')}</p></div></div><button class="link-btn" data-action="review-pending">${t('Review records','Hakiki kumbukumbu')} ${icon('arrow')}</button></section></div><div class="overview-grid"><section class="card"><div class="card-head"><h2>${t('Cash overview','Muhtasari wa miamala')}</h2><label><span class="sr-only">${t('Reporting month','Mwezi wa taarifa')}</span><input class="select-control" style="max-width:165px;font-size:.8125rem" type="month" id="overview-month" value="${month}" max="${TODAY.slice(0,7)}"></label></div>${cashChart()}<div class="legend"><span><i></i>${t('Sales','Mauzo')}</span><span><i class="expense-key"></i>${t('Expenses','Matumizi')}</span></div><div class="balance-row"><span>${t('Net recorded movement','Tofauti ya mauzo na matumizi')}</span><strong>${currency(sum.balance)}</strong></div></section><section class="card readiness"><div class="card-head"><h2>${t('A clearer path to compliance','Hatua rahisi za kufuata')}</h2>${icon('shield')}</div><div class="checklist"><div class="check-item"><span class="step-icon">1</span><div>${t('Capture as you go','Rekodi unapoendelea')}<p>${t('A sale, an expense, or a receipt photo.','Mauzo, matumizi, au picha ya risiti.')}</p></div></div><div class="check-item"><span class="step-icon">2</span><div>${t('Check the important details','Hakiki taarifa muhimu')}<p>${t('You approve every record before it counts.','Unathibitisha kila kumbukumbu kabla ya kuhesabiwa.')}</p></div></div><div class="check-item"><span class="step-icon">3</span><div>${t('Take your summary with you','Pakua muhtasari wako')}<p>${t('Download, review, then continue with TRA.','Pakua, hakiki, kisha endelea kwa TRA.')}</p></div></div></div>${btn(t('Download monthly summary','Pakua muhtasari wa mwezi'),'export-pdf','download','full soft')}</section></div><section class="card"><div class="card-head"><h2>${t('Recent records','Kumbukumbu za karibuni')}</h2><button class="link-btn" data-action="navigate" data-route="records">${t('View all records','Ona zote')} ${icon('arrow')}</button></div>${rows.length?recordsTable(rows,true):empty(t('A fresh page for your business','Anza ukurasa mpya'),t('Record your first sale or expense to see your totals here.','Rekodi mauzo au matumizi ili kuona jumla hapa.'),btn(t('Add a record','Ongeza kumbukumbu'),'new-record','plus','primary'))}</section>`;}
function capture(){const d=getDraft();return header(t('From receipt to a reliable record.','Kutoka risiti hadi kumbukumbu bora.'),t('Capture it. Check it. Keep it.','Nasa. Hakiki. Hifadhi.'))+`<div class="split"><div class="stack capture-side"><section class="card"><div class="tab-row" role="tablist" aria-label="${t('Capture method','Njia ya kurekodi')}"><button role="tab" aria-selected="${captureMode==='scan'}" class="${captureMode==='scan'?'active':''}" data-action="capture-mode" data-mode="scan" ${busy?'disabled':''}>${icon('camera')}${t('Scan receipt','Soma risiti')}</button><button role="tab" aria-selected="${captureMode==='manual'}" class="${captureMode==='manual'?'active':''}" data-action="capture-mode" data-mode="manual" ${busy?'disabled':''}>${icon('edit')}${t('Enter manually','Ingiza mwenyewe')}</button></div>${captureMode==='scan'?`${previewURL?`<div class="receipt-preview"><img src="${previewURL}" alt="${t('Your uploaded receipt for review','Risiti uliyoweka kwa uhakiki')}"></div><div class="sample-actions"><button class="link-btn" data-action="choose-file" ${busy?'disabled':''}>${t('Choose another receipt','Chagua risiti nyingine')}</button></div>`:`<div class="upload-zone" id="drop-zone"><div class="upload-icon">${icon('camera','icon-lg')}</div><h2>${t('Bring your receipt into focus','Piga picha ya risiti yako')}</h2><p>${t('Upload a sample receipt or take a clear, well-lit photo.','Weka risiti ya mfano au piga picha yenye mwanga mzuri.')}</p>${btn(t('Choose a receipt','Chagua risiti'),'choose-file','upload','primary',busy?'disabled':'')}<span class="small muted">JPG, PNG, WebP, PDF · ${t('one page, up to 8 MB','ukurasa mmoja, hadi MB 8')}</span></div>`}<input type="file" id="receipt-file" accept="image/jpeg,image/png,image/webp,application/pdf" class="hidden"><input type="file" id="receipt-camera" accept="image/*" capture="environment" class="hidden"><div class="sample-actions"><button class="link-btn" data-action="take-photo" ${busy?'disabled':''}>${icon('camera')}${t('Take a photo','Piga picha')}</button><button class="link-btn" data-action="try-sample" ${busy?'disabled':''}>${icon('spark')}${t('Try our sample receipt','Jaribu risiti ya mfano')}</button><a href="./sample-receipt.png" download>${t('Download sample','Pakua mfano')}</a></div><div id="processing" class="processing ${busy?'':'hidden'}" role="status" aria-live="polite"><span id="processing-label">${t('Reading receipt…','Inasoma risiti…')}</span><progress id="scan-progress" max="1" value=".05"></progress></div><div id="scan-error" class="form-errors" role="alert"></div>`:`<div class="upload-zone"><div class="upload-icon">${icon('edit','icon-lg')}</div><h2>${t('A few details. A better record.','Taarifa chache. Kumbukumbu bora.')}</h2><p>${t('Use the form to log a sale or expense. The description suggests an editable category.','Tumia fomu kurekodi mauzo au matumizi. Maelezo husaidia kupendekeza aina.')}</p></div>`}</section><div class="note">${icon('shield')} <strong>${t('Your receipt stays on this device.','Risiti inabaki kwenye kifaa hiki.')}</strong> ${t('The first scan loads the reader. No receipt is sent to an AI service. Use fictional or redacted examples in this public prototype.','Usomaji wa kwanza hupakia programu. Risiti haitumwi kwa huduma ya AI. Tumia mifano isiyo na taarifa nyeti.')}</div>${d.text?`<section class="card"><div class="card-head"><h2>${t('What the reader found','Kilichosomwa')}</h2><span class="badge">${d.source==='pdf-text'?'PDF text':t('On-device OCR','OCR kwenye kifaa')}</span></div>${d.confidence!==null&&d.confidence!==undefined?`<p class="small muted">${t('OCR text confidence','Uhakika wa maandishi ya OCR')}: ${Math.round(d.confidence)}%. ${t('This is not a guarantee of field accuracy.','Huu si uhakikisho wa usahihi wa taarifa.')}</p>`:''}<details><summary>${t('Inspect extracted text','Ona maandishi yaliyosomwa')}</summary><pre class="source-text">${e(d.text)}</pre></details></section>`:''}</div><section class="card review-form"><div class="card-head"><div><h2>${t('Review the details','Hakiki taarifa')}</h2><p class="small muted">${t('You have the final say. Every field is editable.','Uamuzi wa mwisho ni wako. Rekebisha taarifa yoyote.')}</p></div><span class="badge review">${t('Review','Hakiki')}</span></div>${d.id?.startsWith('sample-review')?`<div class="note warning">${t('This is a sample review item. Its details are illustrative.','Hii ni kumbukumbu ya mfano ya kuhakiki.')}</div><div class="spacer"></div>`:''}${d.text?`<p class="note warning small">${t('Check the supplier name, receipt reference and date against the image. Text confidence does not confirm these fields.','Hakiki jina la muuzaji, namba ya risiti na tarehe dhidi ya picha. Uhakika wa maandishi hauthibitishi taarifa hizi.')}</p>`:''}<form id="record-form" novalidate><div class="form-grid"><div class="field"><label for="record-type">${t('Transaction type','Aina ya muamala')}</label><select id="record-type" name="type"><option value="expense" ${d.type==='expense'?'selected':''}>${t('Expense · money out','Matumizi · fedha kutoka')}</option><option value="sale" ${d.type==='sale'?'selected':''}>${t('Sale · money in','Mauzo · fedha kuingia')}</option></select></div><div class="field"><label for="record-date">${t('Date','Tarehe')} *</label><input type="date" name="date" id="record-date" max="${TODAY}" value="${e(d.date)}" required></div><div class="field full"><label for="record-description">${t('What was it for?','Muamala ulikuwa wa nini?')} *</label><input id="record-description" name="description" maxlength="300" value="${e(d.description)}" placeholder="${t('e.g. Rice stock from Mwanga Supplies','mf. Mchele kutoka Mwanga Supplies')}" required></div><div class="field full"><label for="record-seller">${t('Seller or customer','Muuzaji au mteja')}</label><input id="record-seller" name="seller" maxlength="150" value="${e(d.seller)}" placeholder="${t('Business or customer name','Jina la biashara au mteja')}"></div><div class="field"><label for="record-amount">${t('Total amount · TZS','Jumla · TZS')} *</label><input id="record-amount" name="amount" inputmode="numeric" value="${e(d.amount)}" placeholder="45,000" required></div><div class="field"><label for="record-vat">${t('Printed tax · TZS','Kodi iliyoandikwa · TZS')}</label><input id="record-vat" name="vat" inputmode="numeric" value="${e(d.vat??'')}" placeholder="${t('If shown on receipt','Ikiwa ipo kwenye risiti')}"><small>${t('Record only what is printed.','Andika iliyo kwenye risiti pekee.')}</small></div><div class="field"><label for="record-category">${t('Category','Aina ya kumbukumbu')}</label><select name="category" id="record-category">${CATEGORIES.map(c=>`<option ${d.category===c?'selected':''} value="${c}">${categoryLabel(c)}</option>`).join('')}</select></div><div class="field"><label for="record-payment">${t('Payment method','Njia ya malipo')}</label><select name="payment" id="record-payment">${['Cash','Mobile money','Bank','Other'].map((p,i)=>`<option value="${p}" ${d.payment===p?'selected':''}>${t(p,['Taslimu','Pesa ya simu','Benki','Nyingine'][i])}</option>`).join('')}</select></div><div class="field full"><label for="record-reference">${t('Receipt or transaction reference','Namba ya risiti au muamala')}</label><input id="record-reference" name="reference" maxlength="80" value="${e(d.reference)}"></div></div><div id="category-reason" class="note" style="margin-top:18px">${t('Category suggestions help organize records. They never decide tax treatment.','Mapendekezo ya aina yanapanga kumbukumbu. Hayaamui kodi.')}</div><div id="record-errors" class="form-errors" role="alert"></div><div id="duplicate-check"></div><div class="form-bottom"><label class="check-label"><input type="checkbox" name="reviewed" id="record-reviewed" ${d.reviewed?'checked':''}>${t('I checked the date, amount and description against the receipt or my records.','Nimehakiki tarehe, kiasi na maelezo kwa risiti au kumbukumbu zangu.')}</label><button type="submit" class="btn primary full" ${busy?'disabled':''}>${icon('check')}${t('Confirm & save record','Thibitisha na hifadhi')}</button><span class="small muted">${t('Saved records update your totals immediately.','Kumbukumbu zilizohifadhiwa husasisha jumla mara moja.')}</span></div></form></section></div>`;}
function recordsView(){const data=filteredRecords();return header(t('Every record, easy to find.','Kila kumbukumbu, kwa urahisi.'),t('Review, correct and export your business history.','Hakiki, rekebisha na pakua historia ya biashara.'),btn('CSV','export-csv','download')+btn(t('Add record','Ongeza'),'new-record','plus','primary'))+`<section class="card"><div class="filters"><div class="field search"><label for="record-search">${t('Search records','Tafuta kumbukumbu')}</label><input type="search" id="record-search" class="search-control" placeholder="${t('Description, party or reference','Maelezo, jina au namba')}" value="${e(query)}"></div><div class="field"><label for="records-month">${t('Month','Mwezi')}</label><input type="month" id="records-month" value="${month}" max="${TODAY.slice(0,7)}"></div><div class="buttons">${btn(t('All months','Miezi yote'),'all-months','','small-btn')}</div></div><div class="card-head"><div class="filter-chips">${[['all',t('All','Zote')],['review',t('Needs review','Za kuhakiki')],['confirmed',t('Confirmed','Zilizothibitishwa')],['sale',t('Sales','Mauzo')],['expense',t('Expenses','Matumizi')],['void',t('Voided','Zilizobatilishwa')]].map(([v,label])=>`<button data-action="filter" data-filter="${v}" class="${filter===v?'active':''}" aria-pressed="${filter===v}">${label}</button>`).join('')}</div><span id="record-count" class="small muted">${data.length} ${t('records','kumbukumbu')}</span></div><div id="records-results">${data.length?recordsTable(data):empty(t('No matching records','Hakuna kumbukumbu'),t('Try another period or add your first transaction.','Jaribu kipindi kingine au ongeza muamala.'))}</div></section><div class="spacer"></div><div class="note">${t('Confirmed records feed the summary. Review items are excluded until you approve them. Corrections are recorded in device activity; voiding retains the original record.','Zilizothibitishwa zinaingia kwenye muhtasari. Za kuhakiki hazijumuishwi hadi uzithibitishe. Marekebisho yanaingia kwenye historia ya kifaa; kubatilisha huhifadhi asili.')}</div>`;}
function filteredRecords(){const q=query.toLowerCase();return state.records.filter(r=>(!month||r.date.startsWith(month))&&(filter==='all'?r.status!=='void':['sale','expense'].includes(filter)?r.type===filter&&r.status!=='void':r.status===filter)&&(!q||[r.description,r.seller,r.reference].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));}
function taxView(){return header(t('An estimate you can understand.','Makadirio unayoweza kuelewa.'),t('Start with your situation. See the rule behind the number.','Anza na hali yako. Ona kanuni iliyotumika.'),routeBtn(t('Reminders','Vikumbusho'),'reminders','calendar'))+`<div class="split"><section class="card"><div class="card-head"><h2>${t('Your annual picture','Muhtasari wako wa mwaka')}</h2><span class="badge">2026</span></div><form id="tax-form"><div class="form-grid"><div class="field full"><label for="business-type">${t('Business type','Aina ya biashara')}</label><select id="business-type" name="business"><option value="retail">${t('Individual retailer · general goods','Mfanyabiashara binafsi · bidhaa za kawaida')}</option><option value="corporate">${t('Registered company','Kampuni iliyosajiliwa')}</option><option value="professional">${t('Professional or technical services','Huduma za kitaalamu')}</option><option value="transport">${t('Passenger or goods transport','Usafiri wa abiria au mizigo')}</option><option value="other">${t('Other / unsure','Nyingine / sina uhakika')}</option></select></div><div class="field full"><label for="annual-turnover">${t('Full-year turnover or projection · TZS','Mauzo ya mwaka au makadirio · TZS')}</label><input id="annual-turnover" name="turnover" inputmode="numeric" value="${lastEstimateInputs?.turnover??''}" placeholder="6,200,000" required><small>${t('Use total sales for the full year, not one month.','Tumia mauzo ya mwaka mzima, si mwezi mmoja.')}</small><button class="link-btn" type="button" data-action="use-recorded-sales">${t('Use confirmed year-to-date sales as a starting point','Anza na mauzo yaliyorekodiwa mwaka huu')}</button></div><div class="field full"><label for="record-quality">${t('Record completeness for the full year','Ukamilifu wa kumbukumbu za mwaka')}</label><select id="record-quality" name="completeRecords"><option value="true">${t('Complete records','Kumbukumbu kamili')}</option><option value="false">${t('Incomplete records','Kumbukumbu zisizokamilika')}</option></select></div><div class="field full"><label class="check-label"><input name="resident" type="checkbox" checked>${t('I am a resident individual with business-only income and have not elected out of presumptive rules.','Mimi ni mkazi binafsi mwenye mapato ya biashara pekee na sijachagua kutoka kwenye mfumo wa makadirio.')}</label><label class="check-label"><input name="newBusiness" type="checkbox">${t('I am seeking relief for a newly started business.','Ninaomba msamaha kwa biashara mpya.')}</label><label class="check-label"><input name="fullYearConfirmed" type="checkbox" required>${t('I confirm the amount is my full-year turnover or a full-year projection.','Nathibitisha kiasi ni mauzo ya mwaka mzima au makadirio ya mwaka.')}</label></div></div><div class="form-bottom"><button class="btn primary full" type="submit">${icon('chart')}${t('Calculate & explain','Hesabu na eleza')}</button><button class="link-btn" type="button" data-action="tax-example">${t('Try a TZS 6.2 million retail example','Jaribu mfano wa mauzo milioni 6.2')}</button></div></form></section><div class="stack"><div id="tax-result">${lastEstimate?taxResultHTML(lastEstimate):`<section class="card tax-output"><div class="eyebrow">${t('Clear inputs. Clear reasoning.','Taarifa wazi. Maelezo wazi.')}</div><h2 style="font-size:1.6rem;line-height:1.35;margin-bottom:20px">${t('Know how your estimate was calculated.','Elewa makadirio yako yalivyohesabiwa.')}</h2><p class="muted">${t('Your result will show the calculation, assumptions and source.','Matokeo yanaonyesha hesabu, masharti na chanzo.')}</p><span class="badge">${t('You review every step','Unahakiki kila hatua')}</span></section>`}</div><section class="card"><h2>${t('Current rule check','Uhakiki wa kanuni')}</h2><p class="small muted">${t('Public guidance reviewed','Mwongozo ulihakikiwa')}: 8 September 2026</p><div class="note warning">${t('For turnover above TZS 11 million, published primary sources show conflicting rates. This calculator withholds that estimate until the enacted rule is verified.','Kwa mauzo zaidi ya milioni 11, vyanzo rasmi vina viwango vinavyotofautiana. Kikokotoo kinasubiri uthibitisho wa kanuni iliyopitishwa.')}</div><div class="spacer"></div>${source('individual')}<div class="spacer" style="height:8px"></div>${source('budget')}<details><summary>${t('Scope and assumptions','Mipaka na masharti')}</summary><ul class="rule-list"><li>${t('General retail by resident individuals with business-only income.','Biashara ya kawaida ya bidhaa, kwa mkazi binafsi mwenye mapato ya biashara pekee.')}</li><li>${t('Expenses do not reduce presumptive turnover.','Matumizi hayapunguzi mauzo yanayotumika kwenye makadirio.')}</li><li>${t('Company, transport and professional-service assessments need their own rules.','Kampuni, usafiri na huduma za kitaalamu zinahitaji kanuni zake.')}</li><li>${t('This is an educational planning tool; TRA has not approved this rule pack.','Hiki ni chombo cha kujifunza na kupanga; TRA haijaidhinisha kanuni za programu hii.')}</li></ul></details></section></div></div>`;}
function taxResultHTML(result){if(result.status==='blocked')return `<section class="card"><div class="notice-icon">${icon('shield')}</div><h2>${t('Verification needed','Uthibitisho unahitajika')}</h2><p class="muted" style="font-size:.875rem;line-height:1.8">${e(result.reason)}</p><div class="buttons"><a class="btn primary" href="${SOURCES.portal.url}" target="_blank" rel="noopener noreferrer">${t('Open TRA portal','Fungua mfumo wa TRA')}${icon('external')}</a>${btn(t('Download worksheet','Pakua maelezo'),'export-estimate','download')}</div></section>`;return `<section class="card tax-output"><div class="eyebrow">${t('Annual planning estimate','Makadirio ya kupanga kwa mwaka')}</div><div class="amount">${currency(result.amount)}</div><div class="formula">${e(result.formula)}</div><p class="small muted" style="margin:18px 0">${t('Public-source snapshot. Verify your situation and applicable law with TRA.','Hesabu ya chanzo cha umma. Thibitisha hali yako na sheria kwa TRA.')}</p>${btn(t('Download calculation','Pakua hesabu'),'export-estimate','download','full')}</section>`;}
function articleHTML(a){return `<div class="guide-answer"><h2>${e(a.title[lang==='sw'?1:0])}</h2><p>${e(a.text[lang==='sw'?1:0])}</p>${source(a.source)}${a.action?`<div style="margin-top:17px">${routeBtn(t('Open workspace','Fungua sehemu husika'),a.action,'arrow','small-btn')}</div>`:''}</div>`;}
function helpView(){const matches=guideSelected?[ARTICLES.find(a=>a.id===guideSelected)].filter(Boolean):guideQuery?searchGuidance(guideQuery):[];return header(t('A little guidance goes a long way.','Mwongozo kidogo husaidia sana.'),t('Short, source-linked answers in English and Kiswahili.','Majibu mafupi yenye vyanzo kwa Kiingereza na Kiswahili.'))+`<div class="split"><section class="card"><div class="card-head"><h2>${t('What would you like to understand?','Ungependa kuelewa nini?')}</h2>${icon('help')}</div><form id="guide-form" class="guide-search"><label for="guide-query" class="sr-only">${t('Search guidance','Tafuta mwongozo')}</label><input type="search" class="search-control" id="guide-query" placeholder="${t('e.g. What is VAT?','mf. VAT ni nini?')}" value="${e(guideQuery)}"><button class="btn primary" type="submit">${icon('search')}${t('Find guidance','Tafuta')}</button></form><div aria-live="polite">${matches.length?matches.map(articleHTML).join(''):guideQuery?`<div class="guide-answer"><h2>${t('This needs a person’s advice.','Hili linahitaji ushauri wa mtu.')}</h2><p>${t('I do not have a reliable source-linked answer for that question. Contact TRA for guidance on your specific situation.','Sina jibu la kuaminika lenye chanzo kwa swali hilo. Wasiliana na TRA kuhusu hali yako.')}</p>${source('support')}</div>`:''}</div><div class="article-grid">${ARTICLES.map(a=>`<button class="article-btn" data-action="article" data-article="${a.id}">${icon(a.id==='records'?'records':a.id==='estimate'?'chart':'help')}<span>${e(a.title[lang==='sw'?1:0])}</span></button>`).join('')}</div></section><div class="stack"><section class="card"><div class="card-head"><h2>${t('Help that knows its limits','Mwongozo unaojua mipaka')}</h2>${icon('shield')}</div><p class="muted" style="font-size:.875rem;line-height:1.8">${t('This prototype searches a curated guidance library. It is not a live generative AI adviser. Receipt OCR uses an actual on-device text-recognition model.','Mfano huu unatafuta kwenye mwongozo ulioandaliwa. Si mshauri wa AI anayezalisha majibu moja kwa moja. OCR hutumia modeli halisi ya kusoma maandishi.')}</p><div class="note">${t('No invented answers, automatic penalties or hidden filing actions. For an individual case, use the official support route.','Hakuna majibu ya kubuni, faini za moja kwa moja au uwasilishaji uliojificha. Kwa kesi binafsi, tumia msaada rasmi.')}</div></section><section class="card"><h2>${t('Continue with TRA','Endelea kwa TRA')}</h2><p class="small muted">${t('These links open the official services.','Viungo hivi vinafungua huduma rasmi.')}</p><div class="stack">${source('portal')}${source('support')}${source('starting')}</div><div class="spacer"></div>${btn(t('Download my question','Pakua swali langu'),'export-question','download','full')}</section></div></div>`;}
function aboutView(){const modules=[
 [t('Digital taxpayer portal','Huduma za mlipakodi'),t('Demonstrated','Imeonyeshwa'),t('Records, tax estimates and links to official services. Filing and payments require authorized integration.','Kumbukumbu, makadirio na viungo rasmi. Ritani na malipo vinahitaji muunganiko ulioidhinishwa.')],
 [t('AI compliance support','Usaidizi wa uzingatiaji kwa AI'),t('Demonstrated','Imeonyeshwa'),t('On-device receipt reading, explainable matching signals and a human review queue. Model-based risk assessment is planned.','Usomaji wa risiti kwenye kifaa, ishara zinazoelezeka na uhakiki wa mtu. Tathmini ya hatari kwa modeli imepangwa.')],
 [t('National e-invoicing','Ankara za kielektroniki'),t('Planned','Imepangwa'),t('Official fiscal numbering, signing and TRA integration remain future work.','Namba rasmi, usaini na muunganiko wa TRA ni kazi ya baadaye.')],
 [t('Revenue analytics','Uchanganuzi wa mapato'),t('Demonstrated','Imeonyeshwa'),t('Record-derived summaries work here. National, sector and regional reporting need authorized datasets.','Muhtasari wa kumbukumbu unafanya kazi. Ripoti za kitaifa, sekta na mikoa zinahitaji data iliyoidhinishwa.')],
 [t('Small-business assistant','Msaidizi wa biashara ndogo'),t('Working','Inafanya kazi'),t('Bilingual curated guidance, records, estimates, reminders and exports.','Mwongozo wa lugha mbili, kumbukumbu, makadirio, vikumbusho na upakuaji.')],
 [t('Secure integration layer','Muunganiko salama'),t('Planned','Imepangwa'),t('This device prototype has no shared TRA database or authenticated officer accounts.','Mfano huu hauna hifadhidata ya pamoja ya TRA au akaunti rasmi za maafisa.')]
 ];return header(t('A connected proposal. A working foundation.','Pendekezo lililounganishwa. Msingi unaofanya kazi.'),t('The six modules from the submitted TIDRE proposal, with clear delivery status.','Moduli sita za pendekezo la TIDRE, pamoja na hali ya utekelezaji.'))+`<div class="buttons" style="margin-bottom:24px">${routeBtn(t('Try officer review','Jaribu uhakiki wa afisa'),'officer','shield','primary')}${routeBtn(t('Read a sample receipt','Soma risiti ya mfano'),'capture','camera')}</div><section class="card"><div class="card-head"><h2>${t('Proposal to prototype','Kutoka pendekezo hadi mfano')}</h2><span class="badge">14 Sep 2026 · v2.1</span></div>${modules.map(([name,status,desc])=>`<div class="capability"><div><strong>${name}</strong><p>${desc}</p></div><span class="badge">${status}</span></div>`).join('')}</section><div class="spacer"></div><section class="card"><div class="card-head"><h2>${t('Submitted 12-month roadmap','Mpango uliowasilishwa wa miezi 12')}</h2><span class="badge review">${t('Proposed · not achieved results','Pendekezo · si matokeo yaliyofikiwa')}</span></div><div class="roadmap-grid">${[['1–2','Plan & requirements','Mipango na mahitaji'],['3–6','Build & integrate','Ujenzi na muunganiko'],['7–8','Pilot','Majaribio'],['9–10','Rollout','Usambazaji'],['11–12','Improve','Uboreshaji']].map(([time,en,sw])=>`<div class="note"><strong>${t('Months','Miezi')} ${time}</strong><p>${t(en,sw)}</p></div>`).join('')}</div><p class="small muted">${t('Pilot baselines and targets must be established before testing. Record completeness, correction rates, task time and officer review quality should be measured. The submitted PDF remains the original proposal.','Viwango vya awali na malengo ya majaribio viwekwe kabla ya upimaji. Pima ukamilifu, marekebisho, muda wa kazi na ubora wa uhakiki. PDF iliyowasilishwa inabaki pendekezo la awali.')}</p></section><div class="spacer"></div><section class="card"><h2>${t('TRA references','Vyanzo vya TRA')}</h2><p>${t('TIDRE complements the official services with clearer records and review support.','TIDRE inasaidia huduma rasmi kwa kumbukumbu na uhakiki bora.')}</p><div class="footer-links">${source('individual')}${source('vat')}${source('portal')}<a class="source-link" href="https://verify.tra.go.tz/Home/Index" target="_blank" rel="noopener noreferrer">${t('TRA receipt verification','Uhakiki wa risiti wa TRA')} ↗</a></div></section>`;}
function settingsView(){return header(t('Your workspace, your control.','Eneo lako, udhibiti wako.'),t('Manage your example business, exports and local history.','Simamia biashara ya mfano, upakuaji na historia ya kifaa.'))+`<div class="split"><div class="stack"><section class="card"><h2>${t('Example business','Biashara ya mfano')}</h2><p class="small muted">${t('Use fictional details. No TIN, password or OTP is needed.','Tumia taarifa za mfano. TIN, nywila au OTP haihitajiki.')}</p><form id="profile-form"><div class="form-grid"><div class="field full"><label for="profile-name">${t('Business name','Jina la biashara')}</label><input id="profile-name" name="name" maxlength="70" value="${e(state.profile.name)}" required></div><div class="field full"><label for="profile-location">${t('Location','Eneo')}</label><input id="profile-location" name="location" maxlength="80" value="${e(state.profile.location)}" required></div></div><div class="spacer"></div><button class="btn primary" type="submit">${t('Save details','Hifadhi taarifa')}</button></form></section><section class="card"><h2>${t('Keep a copy','Hifadhi nakala')}</h2><p class="small muted">${t('A JSON backup includes records and activity. Receipt images remain on the original device; download each source separately from its record. Import merges valid records and skips existing IDs.','Nakala ya JSON ina kumbukumbu na historia. Picha za risiti zinabaki kwenye kifaa cha awali; zipakue kwenye kumbukumbu. Uingizaji unaunganisha kumbukumbu na kuruka zilizopo.')}</p><div class="buttons">${btn(t('Export backup','Pakua nakala'),'backup','download')}${btn(t('Import records','Ingiza kumbukumbu'),'import','upload')}</div><input id="backup-file" type="file" accept="application/json,.json" class="hidden"></section><section class="card"><h2>${t('Choose your starting point','Chagua mwanzo wako')}</h2><p class="small muted">${t('Starting again replaces the records in this browser. Export a backup first if you want to keep them.','Kuanza tena hubadilisha kumbukumbu kwenye kivinjari hiki. Pakua nakala kwanza ili kuzihifadhi.')}</p><div class="buttons">${btn(t('Empty sandbox','Mfano tupu'),'reset-empty','','danger')}${btn(t('Restore sample data','Rudisha data ya mfano'),'reset-sample')}</div></section></div><div class="stack"><section class="card"><div class="card-head"><h2>${t('Privacy in this prototype','Faragha kwenye mfano huu')}</h2>${icon('shield')}</div><p class="muted" style="font-size:.875rem;line-height:1.8">${t('Records are stored in this browser, and receipt files on this device. They are not synchronized across devices, encrypted as a secure vault, sent to TRA, or sent to an AI API. Anyone using this browser profile may access them. Clearing browser data removes them.','Kumbukumbu huhifadhiwa kwenye kivinjari hiki na faili kwenye kifaa. Hazilandanishwi, si hazina iliyosimbwa, wala hazitumwi TRA au kwa API ya AI. Anayetumia kivinjari hiki anaweza kuziona. Kufuta data ya kivinjari huziondoa.')}</p><div class="note warning">${t('Use sample or redacted documents. Real taxpayer data requires the secure pilot service described in the proposal.','Tumia risiti za mfano au zilizofichwa taarifa nyeti. Data halisi inahitaji huduma salama iliyo kwenye pendekezo.')}</div></section><section class="card"><div class="card-head"><h2>${t('Device activity','Historia ya kifaa')}</h2>${btn('JSON','export-activity','download','small-btn')}</div><p class="small muted">${t('A local change history, not a tamper-proof audit log.','Historia ya mabadiliko kwenye kifaa; si rekodi isiyoweza kubadilishwa.')}</p><div class="timeline">${state.events.length?state.events.slice(-12).reverse().map(a=>`<div class="timeline-item"><strong>${e(a.action)}</strong><p>${e(new Date(a.at).toLocaleString(lang==='sw'?'sw-TZ':'en-GB'))}</p>${a.details?.id?`<span class="small muted">${e(a.details.id)}</span>`:''}</div>`).join(''):`<p class="small muted">${t('Your actions will appear here.','Vitendo vyako vitaonekana hapa.')}</p>`}</div></section></div></div>`;}
function remindersView(){return header(t('A small reminder. One less worry.','Kikumbusho kidogo. Wasiwasi mdogo.'),t('Set a personal review date or add a confirmed TRA deadline.','Weka siku ya uhakiki au tarehe ya TRA uliyothibitisha.'))+`<div class="split"><section class="card"><h2>${t('Create a reminder','Tengeneza kikumbusho')}</h2><p class="small muted">${t('Confirm statutory dates and obligations in the official portal before adding them.','Thibitisha tarehe za kisheria kwenye mfumo rasmi kabla ya kuziweka.')}</p><form id="reminder-form"><div class="form-grid"><div class="field full"><label for="reminder-title">${t('What do you need to do?','Unahitaji kufanya nini?')}</label><input id="reminder-title" name="title" maxlength="100" placeholder="${t('Review my monthly records','Hakiki kumbukumbu za mwezi')}" required></div><div class="field full"><label for="reminder-date">${t('Date','Tarehe')}</label><input type="date" id="reminder-date" name="date" value="${TODAY}" min="${TODAY}" required></div></div><div class="spacer"></div><button class="btn primary full" type="submit">${icon('plus')}${t('Save reminder','Hifadhi kikumbusho')}</button></form></section><section class="card"><div class="card-head"><h2>${t('Upcoming reminders','Vikumbusho vyako')}</h2>${icon('calendar')}</div>${state.reminders.length?state.reminders.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<div class="reminder-item"><div><p>${e(r.title)}</p><small>${e(dateLabel(r.date))}</small></div><div class="buttons">${btn(t('Calendar file','Faili ya kalenda'),'download-reminder','download','small-btn',`data-id="${e(r.id)}"`)}<button class="icon-btn" data-action="delete-reminder" data-id="${e(r.id)}" aria-label="${t('Remove reminder','Ondoa kikumbusho')}">${icon('trash')}</button></div></div>`).join(''):empty(t('Nothing scheduled yet','Hakuna kilichopangwa'),t('Add a date that matters to your business.','Ongeza tarehe muhimu kwa biashara yako.'))}<div class="spacer"></div><div class="note">${t('Download and open the .ics file in your calendar to receive its reminders. Saving here alone does not send a notification or sync an account.','Pakua na ufungue faili ya .ics kwenye kalenda ili upokee vikumbusho. Kuhifadhi hapa pekee hakutumi arifa wala kuunganisha akaunti.')}</div><div class="spacer"></div>${source('portal')}</section></div>`;}
function render(){document.documentElement.lang=lang;document.documentElement.dataset.theme=theme;const nav=[['overview','home',t('Overview','Muhtasari')],['capture','camera',t('Capture','Nasa')],['records','records',t('Records','Kumbukumbu')],['tax','chart',t('Tax workspace','Kodi')],['help','help',t('Help','Msaada')]];const pending=state.records.filter(r=>r.status==='review').length;const view={officer:()=>officerView(state,officerSelected,t),overview,capture,records:recordsView,tax:taxView,help:helpView,about:aboutView,settings:settingsView,reminders:remindersView}[route];app.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#overview"><img src="./icon.svg" alt=""><span>TIDRE</span></a><div class="nav-label">${t('YOUR WORKSPACE','ENEO LAKO')}</div><nav class="nav-links" aria-label="${t('Main navigation','Menyu kuu')}">${nav.map(([id,name,label])=>`<button class="nav-btn ${route===id?'active':''}" data-action="navigate" data-route="${id}" ${route===id?'aria-current="page"':''}>${icon(name)}${label}${id==='records'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-btn ${route==='officer'?'active':''}" data-action="navigate" data-route="officer">${icon('shield')}${t('Officer review','Uhakiki wa afisa')}</button><button class="nav-btn ${route==='reminders'?'active':''}" data-action="navigate" data-route="reminders">${icon('calendar')}${t('Reminders','Vikumbusho')}</button><button class="nav-btn ${route==='settings'?'active':''}" data-action="navigate" data-route="settings">${icon('settings')}${t('Workspace settings','Mipangilio')}</button><button class="nav-btn ${route==='about'?'active':''}" data-action="navigate" data-route="about">${icon('info')}${t('About the prototype','Kuhusu mfano')}</button><div class="side-note"><strong>${t('Independent prototype','Mfano huru')}</strong>${t('Built for better business records. Not an official TRA service.','Kwa kumbukumbu bora. Si huduma rasmi ya TRA.')}</div></div></aside><div class="workspace"><header class="topbar"><div class="business-switch"><span class="business-avatar">${icon('store')}</span><div><div class="business-name">${e(state.profile.name)}</div><div class="business-location">${e(state.profile.location)} · ${t('Example workspace','Biashara ya mfano')}</div></div></div><div class="toolbar"><span class="connection">${icon('wifi')}${navigator.onLine?t('Device storage','Kwenye kifaa'):t('Offline','Bila mtandao')}</span><div class="language" aria-label="${t('Language','Lugha')}"><button data-action="language" data-lang="en" class="${lang==='en'?'active':''}" aria-pressed="${lang==='en'}">EN</button><button data-action="language" data-lang="sw" class="${lang==='sw'?'active':''}" aria-pressed="${lang==='sw'}">SW</button></div><button class="icon-btn" data-action="theme" aria-label="${t('Switch color theme','Badili mandhari')}">${icon(theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="navigate" data-route="settings" aria-label="${t('Workspace settings','Mipangilio')}">${icon('settings')}</button></div></header><main id="main" class="page" tabindex="-1"><div class="sample-strip">${icon('info')}<span>${t('Independent prototype · use sample data. Records stay in this browser.','Mfano huru · tumia data ya mfano. Kumbukumbu zinabaki kwenye kivinjari.')}</span><button class="link-btn" data-action="navigate" data-route="officer">${t('Officer review','Uhakiki wa afisa')}</button><button class="link-btn" data-action="navigate" data-route="about">${t('What works','Kinachofanya kazi')}</button></div>${storageIssue?`<div class="note error" role="alert">${t('Storage is unavailable. Changes cannot be saved.','Hifadhi haipatikani. Mabadiliko hayawezi kuhifadhiwa.')} ${e(storageIssue)}</div><div class="spacer"></div>`:''}${view()}<footer class="footnote">TIDRE ${APP_VERSION} · ${t('Independent innovation prototype. No assessment, filing or payment is made here.','Mfano huru wa ubunifu. Hakuna ukadiriaji rasmi, ritani au malipo hapa.')}<div class="footer-links"><button data-action="navigate" data-route="about">${t('Capabilities & pilot','Uwezo na majaribio')}</button><button data-action="navigate" data-route="settings">${t('Privacy & backup','Faragha na nakala')}</button><button data-action="navigate" data-route="reminders">${t('Reminders','Vikumbusho')}</button>${source('portal')}</div></footer></main></div><nav class="bottom-nav" aria-label="${t('Mobile navigation','Menyu ya simu')}">${nav.map(([id,name,label])=>`<button data-action="navigate" data-route="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(name)}${label}</button>`).join('')}</nav></div>`;bindViews();}
function navigate(to){if(!allowed.includes(to))return;if(to!==route){route=to;history.replaceState(null,'','#'+route);render();document.getElementById('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}else render();}
function newRecord(){if(draft?.dirty){modal(t('Continue your unfinished record?','Endelea na kumbukumbu yako?'),`<p>${t('You have an unfinished record. You can continue it or discard it to start another.','Una kumbukumbu isiyokamilika. Endelea nayo au iache uanze nyingine.')}</p><div class="buttons">${btn(t('Discard and start','Acha na anza'),'discard-draft','','danger')}${btn(t('Continue record','Endelea'),'continue-draft','','primary')}</div>`);return;}draft=null;setPreview('');captureMode='scan';navigate('capture');}
function setPreview(url){if(previewURL)URL.revokeObjectURL(previewURL);previewURL=url;}
async function openRecord(id){const r=state.records.find(r=>r.id===id);if(!r)return;if(r.status==='review'){await editRecord(id);return;}modal(t('Record details','Taarifa za kumbukumbu'),`<p><strong>${e(r.description)}</strong><br>${e(dateLabel(r.date))} · ${currency(r.amount)}</p>${statusBadge(r.status)}<div class="spacer"></div><div class="note">${t('Party','Jina')}: ${e(r.seller||'—')}<br>${t('Category','Aina')}: ${categoryLabel(r.category)}<br>${t('Reference','Namba')}: ${e(r.reference||'—')}<br>${t('Source','Chanzo')}: ${e(r.source||'manual')}</div><div class="buttons">${r.sourceId?btn(t('Download source','Pakua asili'),'download-source','download','',`data-id="${e(r.id)}"`):''}${btn(t('Business receipt PDF','Risiti ya biashara PDF'),'receipt-pdf','download','',`data-id="${e(r.id)}"`)}${r.status!=='void'?btn(t('Correct record','Rekebisha'),'edit-record','edit','primary',`data-id="${e(r.id)}"`)+btn(t('Void record','Batilisha'),'void-record','trash','danger',`data-id="${e(r.id)}"`):''}</div><p class="small" style="margin-top:20px">${t('Downloaded business receipts are marked “Not a fiscal receipt”.','Risiti zinazopakuliwa zimeandikwa “Not a fiscal receipt”.')}</p>`);}
async function editRecord(id){const r=state.records.find(r=>r.id===id);if(!r||r.status==='void')return;if(draft?.dirty&&draft.id!==id){toast(t('Finish your current record before editing another.','Maliza kumbukumbu yako kabla ya nyingine.'));navigate('capture');return;}closeModal();draft={...structuredClone(r),reviewed:false,dirty:true};captureMode='manual';setPreview('');if(r.sourceId){const evidence=await getEvidence(r.sourceId);if(evidence){setPreview(URL.createObjectURL(evidence.previewFile||evidence.file));captureMode='scan';}}navigate('capture');}
function bindViews(){document.getElementById('overview-month')?.addEventListener('change',ev=>{if(ev.target.value){month=ev.target.value;render();}});document.getElementById('records-month')?.addEventListener('change',ev=>{month=ev.target.value;render();});document.getElementById('record-search')?.addEventListener('input',ev=>{query=ev.target.value;const rows=filteredRecords();document.getElementById('record-count').textContent=rows.length+' '+t('records','kumbukumbu');document.getElementById('records-results').innerHTML=rows.length?recordsTable(rows):empty(t('No matching records','Hakuna kumbukumbu'),t('Try another search.','Jaribu kutafuta tena.'));});
 const form=document.getElementById('record-form');form?.addEventListener('input',ev=>{if(!ev.target.name||!draft)return;draft[ev.target.name]=ev.target.type==='checkbox'?ev.target.checked:ev.target.value;draft.dirty=true;if(['description','type'].includes(ev.target.name)){const suggestion=suggestCategory(draft.description,draft.type);draft.category=suggestion.category;document.getElementById('record-category').value=suggestion.category;document.getElementById('category-reason').textContent=t(suggestion.reason,'Aina imependekezwa kutoka kwenye maelezo. Hakiki kabla ya kuhifadhi.');}if(ev.target.name!=='reviewed'&&ev.target.name!=='duplicateReason'&&ev.target.name!=='duplicateOverride'){draft.reviewed=false;document.getElementById('record-reviewed').checked=false;}});form?.addEventListener('submit',saveRecord);
 document.getElementById('receipt-file')?.addEventListener('change',ev=>{if(ev.target.files[0])scanFile(ev.target.files[0]);});document.getElementById('receipt-camera')?.addEventListener('change',ev=>{if(ev.target.files[0])scanFile(ev.target.files[0]);});const zone=document.getElementById('drop-zone');zone?.addEventListener('dragover',ev=>{ev.preventDefault();zone.classList.add('dragging');});zone?.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone?.addEventListener('drop',ev=>{ev.preventDefault();zone.classList.remove('dragging');if(ev.dataTransfer.files[0])scanFile(ev.dataTransfer.files[0]);});
 document.getElementById('tax-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);lastEstimateInputs={turnover:parseAmount(f.get('turnover')),completeRecords:f.get('completeRecords')==='true',resident:f.get('resident')==='on',business:f.get('business'),year:'2026',fullYearConfirmed:f.get('fullYearConfirmed')==='on',newBusiness:f.get('newBusiness')==='on'};lastEstimate=calculatePresumptive(lastEstimateInputs);document.getElementById('tax-result').innerHTML=taxResultHTML(lastEstimate);document.getElementById('tax-result').scrollIntoView({block:'nearest',behavior:'smooth'});});
 document.getElementById('guide-form')?.addEventListener('submit',ev=>{ev.preventDefault();guideQuery=document.getElementById('guide-query').value.trim().slice(0,200);guideSelected='';render();});
 document.getElementById('profile-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);const name=String(f.get('name')).trim(),location=String(f.get('location')).trim();if(!name||!location)return;try{commit(s=>{s.profile.name=name.slice(0,70);s.profile.location=location.slice(0,80);},'Example profile updated');render();toast(t('Workspace details saved.','Taarifa zimehifadhiwa.'));}catch(err){toast(err.message);}});
 document.getElementById('backup-file')?.addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Choose a JSON backup smaller than 8 MB.');const rows=validateBackup(JSON.parse(await file.text()));let added=0;commit(s=>{const known=new Set(s.records.map(r=>r.id));for(const r of rows){if(!known.has(r.id)){s.records.push(r);known.add(r.id);added++;}}},'Backup records imported',{records:rows.length});render();toast(t(`${added} records imported; existing IDs were kept.`,`Kumbukumbu ${added} zimeingizwa; zilizokuwepo zimebaki.`));}catch(err){toast(err.message);}});
 document.getElementById('reminder-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);const title=String(f.get('title')).trim(),date=String(f.get('date'));if(!title||!validDate(date)||date<TODAY)return;try{commit(s=>s.reminders.push({id:crypto.randomUUID(),title:title.slice(0,100),date}),'Personal reminder added');render();toast(t('Reminder saved. Download its calendar file to receive an alert.','Kikumbusho kimehifadhiwa. Pakua faili ya kalenda ili upate arifa.'));}catch(err){toast(err.message);}});
}
async function scanFile(file){if(busy)return;busy=true;captureMode='scan';getDraft();render();try{const result=await extractDocument(file,(label,value)=>{const el=document.getElementById('processing-label');if(el)el.textContent=t(label+'…','Inasoma risiti…');const p=document.getElementById('scan-progress');if(p)p.value=value;});const fields=parseReceipt(result.text);const sourceId=crypto.randomUUID();await putEvidence(sourceId,file,result.imageBlob);const previousId=draft?.sourceId;if(previousId&&!state.records.some(r=>r.sourceId===previousId))await deleteEvidence(previousId);const d=getDraft();draft={...d,...fields,amount:fields.amount??'',vat:fields.vat??'',sourceId,sourceHash:result.sourceHash,confidence:result.confidence,source:result.method,description:fields.seller?fields.seller+' receipt':d.description,reviewed:false,dirty:true};draft.category=suggestCategory(fields.text,draft.type).category;setPreview(URL.createObjectURL(result.imageBlob));busy=false;render();toast(fields.uncertain.length?t('Read complete. Some details need your attention.','Usomaji umekamilika. Baadhi ya taarifa zinahitaji uhakiki.'):t('Receipt read. Please check every field before saving.','Risiti imesomwa. Hakiki kila taarifa kabla ya kuhifadhi.'));}catch(err){busy=false;render();const box=document.getElementById('scan-error');if(box)box.textContent=err.message;toast(t('Reading failed. You can still enter the details manually.','Usomaji umeshindikana. Unaweza kuingiza taarifa mwenyewe.'));}}
async function saveRecord(ev){ev.preventDefault();if(busy)return;const f=new FormData(ev.currentTarget),d=getDraft();const record={...d,type:String(f.get('type')),date:String(f.get('date')),description:String(f.get('description')).trim(),seller:String(f.get('seller')).trim(),amount:parseAmount(f.get('amount')),vat:String(f.get('vat')).trim()===''?null:parseAmount(f.get('vat')),category:String(f.get('category')),payment:String(f.get('payment')),reference:String(f.get('reference')).trim()};const errors=validateRecord(record);if(f.get('reviewed')!=='on')errors.reviewed=t('Please confirm that you reviewed the details.','Thibitisha kwamba umehakiki taarifa.');document.getElementById('record-errors').innerHTML=Object.keys(errors).length?`<ul>${Object.values(errors).map(msg=>`<li>${e(msg)}</li>`).join('')}</ul>`:'';ev.currentTarget.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));Object.keys(errors).forEach(k=>ev.currentTarget.elements.namedItem(k)?.setAttribute('aria-invalid','true'));if(Object.keys(errors).length){document.getElementById('record-errors').scrollIntoView({block:'nearest'});return;}
 const dupes=findDuplicates(state.records,record);if(dupes.length&&!(f.get('duplicateOverride')==='on'&&String(f.get('duplicateReason')||'').trim().length>=8)){document.getElementById('duplicate-check').innerHTML=`<div class="note warning"><strong>${t('A similar record already exists.','Kumbukumbu inayofanana ipo.')}</strong><p class="small" style="margin:8px 0">${e(dupes[0].description)} · ${dateLabel(dupes[0].date)} · ${currency(dupes[0].amount)}</p><label class="check-label"><input type="checkbox" name="duplicateOverride">${t('This is a separate, genuine transaction.','Huu ni muamala tofauti.')}</label><div class="field" style="margin-top:12px"><label for="duplicate-reason">${t('Explain why it is different (at least 8 characters)','Eleza tofauti yake (herufi 8 au zaidi)')}</label><input id="duplicate-reason" name="duplicateReason" maxlength="200" required></div></div>`;document.getElementById('duplicate-check').scrollIntoView({block:'nearest'});return;}
 const existing=state.records.find(r=>r.id===record.id);record.status='confirmed';record.createdAt=existing?.createdAt||new Date().toISOString();record.updatedAt=new Date().toISOString();if(dupes.length)record.duplicateReason=String(f.get('duplicateReason')).trim().slice(0,200);for(const key of ['dirty','reviewed','uncertain','duplicateOverride'])delete record[key];try{commit(s=>{const index=s.records.findIndex(r=>r.id===record.id);if(index>=0)s.records[index]=record;else s.records.push(record);},existing?'Record corrected and confirmed':'Record reviewed and saved',{id:record.id,before:existing||null,after:record});draft=null;setPreview('');filter='all';month=record.date.slice(0,7);navigate('records');toast(t('Record saved. Your totals are up to date.','Imehifadhiwa. Jumla imesasishwa.'));}catch(err){document.getElementById('record-errors').textContent=t('Save failed. Your record is still open; export or free storage before trying again.','Hifadhi imeshindikana. Kumbukumbu bado ipo wazi.')+' '+err.message;}}

document.addEventListener('click',async ev=>{const target=ev.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;try{
 if(action==='navigate'){ev.preventDefault();navigate(target.dataset.route);}
 else if(action==='officer-case'){officerSelected=target.dataset.id;render();}
 else if(action==='officer-back'){officerSelected='';render();}
 else if(action==='officer-save'){const c=reviewCases(state.records).find(c=>c.record.id===target.dataset.id);if(!c)return;const note=document.getElementById('officer-note').value.trim();const outcome=document.getElementById('officer-outcome').value;if(note.length<8){document.getElementById('officer-error').textContent=t('Describe the evidence and next step in at least 8 characters.','Eleza ushahidi na hatua kwa angalau herufi 8.');return;}if(!['clarify','reviewed'].includes(outcome))return;commit(s=>{s.officerReviews??={};s.officerReviews[c.record.id]={signature:c.signature,note:note.slice(0,500),outcome,at:new Date().toISOString()};},'Officer review recorded',{id:c.record.id,outcome,note:note.slice(0,500)});render();toast(t('Review saved on this device.','Uhakiki umehifadhiwa kwenye kifaa hiki.'));}
 else if(action==='new-record')newRecord();
 else if(action==='language'){lang=target.dataset.lang;try{localStorage.setItem('kr-language',lang);}catch{}render();}
 else if(action==='theme'){theme=theme==='dark'?'light':'dark';try{localStorage.setItem('kr-theme',theme);}catch{}render();}
 else if(action==='close-modal')closeModal();
 else if(action==='capture-mode'){if(busy)return;captureMode=target.dataset.mode;render();}
 else if(action==='choose-file')document.getElementById('receipt-file')?.click();
 else if(action==='take-photo')document.getElementById('receipt-camera')?.click();
 else if(action==='try-sample'){if(busy)return;const response=await fetch(new URL('./sample-receipt.png',import.meta.url));if(!response.ok)throw Error('Sample receipt could not load.');await scanFile(new File([await response.blob()],'sample-receipt.png',{type:'image/png'}));}
 else if(action==='review-pending'){filter='review';navigate('records');}
 else if(action==='filter'){filter=target.dataset.filter;render();}
 else if(action==='all-months'){month='';render();}
 else if(action==='open-record')await openRecord(target.dataset.id);
 else if(action==='edit-record')await editRecord(target.dataset.id);
 else if(action==='discard-draft'){draft=null;setPreview('');closeModal();navigate('capture');}
 else if(action==='continue-draft'){closeModal();navigate('capture');}
 else if(action==='export-csv'){download(csv(filteredRecords()),'TIDRE-Records-'+(month||'all')+'.csv','text/csv;charset=utf-8');toast(t('CSV downloaded.','CSV imepakuliwa.'));}
 else if(action==='export-pdf'){target.disabled=true;await reportPDF(state,month||TODAY.slice(0,7));toast(t('Monthly PDF downloaded.','PDF ya mwezi imepakuliwa.'));}
 else if(action==='receipt-pdf'){target.disabled=true;const r=state.records.find(r=>r.id===target.dataset.id);if(r)await businessReceiptPDF(state.profile,r);}
 else if(action==='download-source'){const r=state.records.find(r=>r.id===target.dataset.id);const stored=await getEvidence(r.sourceId);if(!stored)throw Error('The original receipt is not on this device.');download(stored.file,stored.name||'receipt.png');}
 else if(action==='export-estimate'){if(lastEstimate){target.disabled=true;await estimatePDF(lastEstimate,lastEstimateInputs);}}
 else if(action==='use-recorded-sales'){const sum=totals(state.records.filter(r=>r.date.startsWith('2026')));document.getElementById('annual-turnover').value=sum.sales;toast(t('Year-to-date sales filled. Add expected remaining sales and confirm the full year.','Mauzo hadi sasa yamewekwa. Ongeza yanayotarajiwa na thibitisha mwaka mzima.'));}
 else if(action==='tax-example'){const form=document.getElementById('tax-form');form.elements.turnover.value=6200000;form.elements.business.value='retail';form.elements.completeRecords.value='true';form.elements.resident.checked=true;form.elements.newBusiness.checked=false;form.elements.fullYearConfirmed.checked=true;form.requestSubmit();}
 else if(action==='article'){guideSelected=target.dataset.article;guideQuery='';render();}
 else if(action==='export-question'){download('TIDRE - request for guidance\n\nQuestion: '+(guideQuery||'Please write your question here.')+'\n\nPlease review with TRA through '+SOURCES.support.url+'\nNo information has been sent by this application.\n','TIDRE-Question.txt');}
 else if(action==='backup')download(JSON.stringify({...state,exportedAt:new Date().toISOString(),evidenceIncluded:false},null,2),'TIDRE-Backup-'+TODAY+'.json','application/json');
 else if(action==='import')document.getElementById('backup-file').click();
 else if(action==='export-activity')download(JSON.stringify(state.events,null,2),'TIDRE-Device-Activity.json','application/json');
 else if(action==='void-record'){const r=state.records.find(r=>r.id===target.dataset.id);if(!r)return;modal(t('Void this record?','Batilisha kumbukumbu?'),`<p>${e(r.description)} · ${currency(r.amount)}<br>${t('It will leave your totals. The record and change history will remain.','Itaondoka kwenye jumla. Kumbukumbu na historia vitabaki.')}</p><div class="field"><label for="void-reason">${t('Reason','Sababu')}</label><input id="void-reason" maxlength="200" placeholder="${t('e.g. entered twice','mf. imeingizwa mara mbili')}"></div><div class="buttons">${btn(t('Keep record','Iache'),'close-modal')}${btn(t('Void record','Batilisha'),'confirm-void','trash','danger',`data-id="${e(r.id)}"`)}</div>`);}
 else if(action==='confirm-void'){const reason=document.getElementById('void-reason').value.trim();if(reason.length<5){toast(t('Enter a reason of at least 5 characters.','Andika sababu yenye herufi 5 au zaidi.'));return;}const r=state.records.find(r=>r.id===target.dataset.id);commit(s=>{const row=s.records.find(x=>x.id===r.id);row.status='void';row.voidReason=reason;row.updatedAt=new Date().toISOString();},'Record voided',{id:r.id,before:r,reason});closeModal();render();toast(t('Record voided. Totals updated.','Imebatilishwa. Jumla imesasishwa.'));}
 else if(action==='reset-empty'||action==='reset-sample'){modal(t('Replace this workspace?','Badilisha eneo hili?'),`<p>${t('This replaces all records and local activity in this browser. Download a backup first if needed. Receipt files will be removed from this device.','Hii inabadilisha kumbukumbu na historia katika kivinjari. Pakua nakala kwanza. Faili za risiti zitaondolewa kwenye kifaa.')}</p><div class="buttons">${btn(t('Cancel','Ghairi'),'close-modal')}${btn(t('Export backup','Pakua nakala'),'backup','download')}${btn(t('Replace workspace','Badilisha'),'confirm-reset','','danger',`data-mode="${action==='reset-empty'?'empty':'sample'}"`)}</div>`);}
 else if(action==='confirm-reset'){const oldIds=state.records.map(r=>r.sourceId).filter(Boolean);if(draft?.sourceId)oldIds.push(draft.sourceId);const next=seedState();if(target.dataset.mode==='empty'){next.records=[];next.profile={name:t('My example business','Biashara yangu ya mfano'),location:'Tanzania',mode:'sandbox'};}saveState(next);state=next;draft=null;setPreview('');closeModal();render();for(const id of new Set(oldIds))await deleteEvidence(id);toast(t('Workspace reset.','Eneo limeanzishwa upya.'));}
 else if(action==='download-reminder'){const r=state.reminders.find(r=>r.id===target.dataset.id);download(calendarEvent({...r,description:'Personal reminder from TIDRE. Verify official obligations with TRA.'}),'TIDRE-Reminder-'+r.date+'.ics','text/calendar;charset=utf-8');toast(t('Calendar file downloaded. Open it to add the reminder.','Faili imepakuliwa. Ifungue ili kuongeza kikumbusho.'));}
 else if(action==='delete-reminder'){const r=state.reminders.find(r=>r.id===target.dataset.id);modal(t('Remove reminder?','Ondoa kikumbusho?'),`<p>${e(r.title)} · ${e(dateLabel(r.date))}</p><div class="buttons">${btn(t('Cancel','Ghairi'),'close-modal')}${btn(t('Remove','Ondoa'),'confirm-delete-reminder','','danger',`data-id="${e(r.id)}"`)}</div>`);}
 else if(action==='confirm-delete-reminder'){commit(s=>{s.reminders=s.reminders.filter(r=>r.id!==target.dataset.id);},'Personal reminder removed');closeModal();render();}
 }catch(err){toast(err.message||t('Something went wrong. Please try again.','Hitilafu imetokea. Jaribu tena.'));}finally{if(target.isConnected)target.disabled=false;}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(allowed.includes(next)){route=next;render();}});
window.addEventListener('beforeunload',ev=>{if(draft?.dirty||busy){ev.preventDefault();ev.returnValue='';}});
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
